_helper_git() {
    local params=''
    if declare -F _argc_util_param_select_options >/dev/null 2>&1; then
        params=$(_argc_util_param_select_options -C --git-dir --work-tree)
    fi
    git $params "$@"
}

_helper_local_refs() {
    _helper_git for-each-ref --count=500 --format='%(refname:strip=2)' refs/heads refs/tags 2>/dev/null
}

_helper_ref_files() {
    local ref=$1
    [[ -n $ref ]] || return 0
    _helper_git ls-tree -r --name-only -z "$ref" 2>/dev/null |
        tr '\0' '\n' |
        _argc_util_comp_parts /
}

_helper_refs() {
    local git_dir ref
    git_dir=$(_helper_git rev-parse --absolute-git-dir 2>/dev/null)
    [[ -n $git_dir ]] || return 0
    for ref in HEAD FETCH_HEAD ORIG_HEAD MERGE_HEAD REBASE_HEAD CHERRY_PICK_HEAD REVERT_HEAD BISECT_HEAD AUTO_MERGE; do
        if [[ -e "$git_dir/$ref" ]]; then
            printf '%s\n' "$ref"
        fi
    done
    _helper_git for-each-ref --count=500 --format='%(refname:strip=2)' refs/heads refs/tags refs/remotes 2>/dev/null
}

_helper_remote_refs() {
    local remote=$1
    [[ -n $remote ]] || return 0
    _helper_git for-each-ref --format='%(refname)' "refs/remotes/$remote" 2>/dev/null |
        sed -e "s|^refs/remotes/$remote/||" -e '/^HEAD$/d'
}

_helper_status_paths() {
    local mode=$1
    _helper_git status --porcelain -unormal -z 2>/dev/null |
        gawk -v MODE="$mode" '
            BEGIN { RS = "\0"; skip = 0 }
            {
                if (skip) { skip = 0; next }
                if (substr($0, 1, 1) ~ /[RC]/) skip = 1
                if (MODE == "staged" && substr($0, 2, 1) != " ") next
                if (MODE == "unstaged" && substr($0, 2, 1) == " ") next
                if (MODE == "untracked" && substr($0, 1, 2) != "??") next
                path = substr($0, 4)
                if (path != "") print path
            }' |
        _helper_strip_prefix |
        _argc_util_comp_parts /
}

_helper_strip_prefix() {
    local prefix path
    prefix=$(_helper_git rev-parse --show-prefix 2>/dev/null)
    while IFS= read -r path; do
        [[ -n $path ]] || continue
        if [[ -n $prefix ]]; then
            [[ $path == "$prefix"* ]] || continue
            path=${path#"$prefix"}
        fi
        printf '%s\n' "$path"
    done
}
